// GENERATED by scripts/sync-shared.mjs from src/coach/commentary.ts. Do not edit; run `npm run sync:shared`.
// Running commentary: a verdict on each of the player's moves, decided by the
// engine's evaluation, and a prompt for the coach to say why in one line.
// The engine and the rules supply every fact; Claude only words them.
// Pure functions, unit tested.
import type { Chess } from "chess.js";
import { gameAt, uciLineToSan } from "../chess/notation.js";
import { moverCp } from "../engine/strength.js";
import type { Analysis, Position, Score } from "../engine/uci.js";
import { evaluationInWords, factCheck, redactMoveFacts } from "./hint.js";
import { materialBalance, moveFacts } from "./move-facts.js";

export type Verdict = "good" | "inaccuracy" | "mistake" | "missed";

export const VERDICT_LABEL: Record<Verdict, string> = {
  good: "Good move",
  inaccuracy: "Inaccuracy",
  mistake: "Mistake",
  missed: "Missed chance",
};

/** Win chance lost (in percentage points) from which a move counts as an inaccuracy, or a mistake. */
export const INACCURACY = 10;
export const MISTAKE = 20;
/**
 * Win chance flattens out once a game is decided, so a hung piece in a lost
 * position would look harmless. Losing this many centipawns is a mistake
 * anyway, unless the player stays clearly winning.
 */
const MISTAKE_CP = 250;
const STILL_WINNING_CP = 1000;
/** A best move that wins this much material in the engine's line is a chance. */
const CHANCE_POINTS = 2;

/**
 * Winning chance for the side to move, 0 to 100, from its centipawn score
 * (the same curve lichess uses). A pawn up is worth more in a level position
 * than when already a rook ahead, so losses are measured on this scale.
 */
export function winChance(cp: number): number {
  return 50 + 50 * (2 / (1 + Math.exp(-0.00368208 * cp)) - 1);
}

export interface MoveReview {
  verdict: Verdict;
  /** Win chance lost by the move, in percentage points (0 for the best move). */
  loss: number;
  /** Centipawns lost compared with the best move (0 or less for the best move). */
  cpLoss: number;
  playedSan: string;
  /** True when the player played the engine's best move. */
  isBest: boolean;
  bestSan: string;
  bestUci: string;
  /** What each move does, from the rules. */
  playedFacts: string[];
  bestFacts: string[];
  /** Material the best move wins in the engine's line, in points (negative: it loses some). */
  bestGain: number;
  bestMates: boolean;
  evalBefore: string;
  evalAfter: string;
}

/**
 * Reviews the player's move `playedUci` from `position`. `before` is the
 * engine's analysis of the position before the move (ideally with several
 * lines, so a played candidate is judged within the same search). `after`
 * analyses the position after it, needed only when the move isn't among
 * `before`'s lines. Null when the engine gave too little to judge.
 */
export function reviewMove(
  position: Position,
  before: Analysis,
  after: Analysis | null,
  playedUci: string,
): MoveReview | null {
  const game = gameAt(position);
  const side = game.turn();
  const bestUci = before.bestMove;
  if (!bestUci) return null;
  const lines = before.lines?.length
    ? before.lines
    : [{ multipv: 1, depth: before.depth, score: before.score ?? {}, pv: before.pv }];
  const top = lines[0]!;
  const bestCp = moverCp(top.score, side);

  const playedSan = uciLineToSan(game, [playedUci])[0];
  const bestSan = uciLineToSan(game, [bestUci])[0];
  if (!playedSan || !bestSan) return null;
  const afterGame = gameAt({ ...position, moves: [...(position.moves ?? []), playedUci] });

  // The played move's score, from White's side (as the engine reports it).
  const isBest = playedUci === bestUci;
  const line = lines.find((l) => l.pv[0] === playedUci);
  const playedScore: Score | undefined = isBest ? top.score : (line?.score ?? after?.score);
  if (!playedScore && !afterGame.isCheckmate()) return null;
  const playedCp = afterGame.isCheckmate() ? bestCp : moverCp(playedScore, side);

  const loss = Math.max(0, winChance(bestCp) - winChance(playedCp));
  const bestLine = uciLineToSan(game, top.pv[0] === bestUci ? top.pv : [bestUci]);
  const bestGain = materialGain(game, bestLine);
  const bestMates = top.score.mate !== undefined && moverCp(top.score, side) > 0;
  // Only one legal move, or mate: nothing better was possible.
  const forced = game.moves().length === 1;

  const bigCpLoss = bestCp - playedCp >= MISTAKE_CP && playedCp < STILL_WINNING_CP;
  let verdict: Verdict = "good";
  if (!isBest && !forced && (loss >= INACCURACY || bigCpLoss)) {
    const chance = bestMates || bestGain >= CHANCE_POINTS;
    verdict = chance ? "missed" : loss >= MISTAKE || bigCpLoss ? "mistake" : "inaccuracy";
  }
  return {
    verdict,
    loss: Math.round(loss),
    cpLoss: bestCp - playedCp,
    playedSan,
    isBest,
    bestSan,
    bestUci,
    playedFacts: moveFacts(game, playedSan),
    bestFacts: moveFacts(game, bestSan),
    bestGain,
    bestMates,
    evalBefore: evaluationInWords(top.score),
    evalAfter: afterGame.isCheckmate() ? "checkmate" : evaluationInWords(playedScore!),
  };
}

/** Material the side to move wins over `sans`, in points. */
export function materialGain(game: Chess, sans: string[]): number {
  const end = gameAt({ fen: game.fen() });
  for (const san of sans) end.move(san);
  const sign = game.turn() === "w" ? 1 : -1;
  return sign * (materialBalance(end) - materialBalance(game));
}

/** The comment for a good move: no coach call needed (it saves Claude usage). */
export function goodMoveText(review: MoveReview): string {
  return review.isBest ? "The engine's top choice." : "A good, solid move.";
}

/**
 * An engine-only comment, used when the coach can't be asked or its line
 * fails the check. `hideBest` keeps the better move unnamed.
 */
export function fallbackText(review: MoveReview, hideBest: boolean): string {
  switch (review.verdict) {
    case "good":
      return goodMoveText(review);
    case "missed":
      return hideBest
        ? "You missed a chance, and it may still be there. Look again!"
        : `You missed ${review.bestSan}.`;
    case "mistake":
      return hideBest
        ? "The engine found a clearly better move."
        : `${review.bestSan} was clearly better.`;
    case "inaccuracy":
      return hideBest
        ? "There was a slightly better move."
        : `${review.bestSan} was a little better.`;
  }
}

/**
 * Prompt for one line of commentary on a move that wasn't good. The verdict
 * is the engine's and is shown by the page; the coach only says why.
 */
export function buildCommentPrompt(review: MoveReview, hideBest: boolean): string {
  const best = hideBest
    ? [
        "The better move (kept secret: it may still be on the board for the player to find):",
        ...redactMoveFacts(review.bestFacts).map((f) => `- ${f}`),
      ]
    : [`The engine's best move: ${review.bestSan}`, ...review.bestFacts.map((f) => `- ${f}`)];
  if (review.bestGain > 0)
    best.push(`- In the engine's line it wins ${review.bestGain} points of material.`);
  if (review.bestMates) best.push("- It leads to a forced mate.");
  return [
    "You are the coach in Chess Coach, commenting on a beginner's last move in a practice game.",
    "Use ONLY the engine facts below. Do not calculate variations yourself, and never claim",
    "a move attacks, defends, wins or threatens anything that is not listed.",
    `The page already shows the engine's verdict ("${VERDICT_LABEL[review.verdict]}"): don't repeat`,
    "it or contradict it. Write ONE short sentence, at most 20 words, in plain English, saying",
    "why, in standard algebraic notation. Mention no move other than the ones named below.",
    ...(hideBest
      ? ["Don't name the better move, its piece or its squares: let the player look for it."]
      : []),
    "",
    "Engine facts:",
    `Verdict: ${VERDICT_LABEL[review.verdict]} (the move lost ${review.loss}% winning chance).`,
    `Evaluation before the move: ${review.evalBefore}. After it: ${review.evalAfter}.`,
    `The player played: ${review.playedSan}`,
    ...review.playedFacts.map((f) => `- ${f}`),
    ...best,
  ].join("\n");
}

/**
 * Whether the better move must stay unnamed: while it is still a legal move
 * for the player, naming it would hand over the move to play now. `moves` is
 * the game now; before the engine has replied it is always kept hidden.
 */
export function bestStillThere(moves: readonly string[], playerToMove: boolean, bestUci: string) {
  if (!playerToMove) return true;
  return gameAt({ moves: [...moves] })
    .moves({ verbose: true })
    .some((m) => m.from === bestUci.slice(0, 2) && m.to === bestUci.slice(2, 4));
}

/**
 * Whether the coach's line may be shown: complete, naming only moves played
 * (or the better move, when it may be named), and not giving a hidden better
 * move away. Otherwise the engine's own line is shown.
 */
export function acceptComment(
  text: string,
  truncated: boolean,
  review: MoveReview,
  hideBest: boolean,
  played: readonly string[],
): boolean {
  if (!text || truncated) return false;
  const allowed = hideBest ? [...played] : [...played, review.bestSan];
  const best = { bestMove: review.bestSan, bestMoveTo: review.bestUci.slice(2, 4) };
  // "piece" checks only the move and its destination; "move" checks nothing.
  const fc = factCheck(text, hideBest ? "piece" : "move", best, allowed);
  return !fc.unknownMoves.length && !fc.revealedMove;
}
